import MenuJson from "./menus.json";

export default {
  name: "Navbar",
  data() {
    return {
      menu: MenuJson,
      isLanguage: true,
    };
  },
  created() {},
  methods: {},
  beforeRouteLeave(to, from, next) {
    window.history.replaceState(null, "", "/");
    next();
}
};
